out = {'_note': 'dict 배치15 — 22:191~230 40개. {Ln}은 원본 링크 토큰으로 자동 치환됨.'}
for k, tpl in TPL.items():
    links = LINKS[k]
    text = tpl
    for i, lk in enumerate(links):
        ph = '{L%d}' % i
        if ph not in text:
            raise SystemExit('%s: 플레이스홀더 %s 없음 (링크 %d개 필요) text=%s' % (k, ph, len(links), text))
        text = text.replace(ph, lk)
    if '{L' in text:
        raise SystemExit('%s: 치환 안 된 플레이스홀더 남음: %s' % (k, text))
    out[k] = text

json.dump(out, io.open('work/e4_dict_kr_batch15.json', 'w', encoding='utf-8'),
          ensure_ascii=False, indent=1)
print('배치15 %d개 -> work/e4_dict_kr_batch15.json' % (len(out) - 1))
